import React from 'react';
import {
  Box,
  Typography,
  IconButton,
  Paper,
  Stack,
  useTheme
} from '@mui/material';
import {
  Savings,
  AccountBalanceWallet,
  Payment,
  PersonOutline
} from '@mui/icons-material';
import { Link, useNavigate } from 'react-router-dom';
import ImageIconButton from '../../Component/ImageIconButton';
import Menu1 from '../../assets/Menu1.png'
import Menu2 from '../../assets/Menu2.png'
import Menu3 from '../../assets/Menu3.png'
import Menu4 from '../../assets/Menu4.png'
const menuItems = [
  { label: 'จองสินค้า', path: 'downPayment', icon:  Menu1,counter :0  },
  { label: 'สินเชื่อ', path: 'loan', icon: Menu2 },
  { label: 'ค่าบริการอื่นๆ', path: 'Invoice', icon: Menu2 },
  { label: 'ประวัติการชำระเงิน', path: 'paid', icon: Menu3 },
  // { label: 'ข้อมูลส่วนตัว', path: 'profile', icon: Menu4 },
];

const HomeMenu = () => {
  const theme = useTheme();
  const navigate = useNavigate();

  return (
    <Box p={3}>
      <Box
        display="flex"
        flexWrap="wrap"
        justifyContent="center"
        gap={2}
      >
        {menuItems.map((item) => (
          <Link key={item.path} to={item.path} style={{ textDecoration: 'none' }}>
            <Paper
              elevation={1}
              sx={{
                width: 120,
                height: 120,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                background: theme.palette.info.main,
                boxShadow:3,
                borderRadius:5
              }}
            >
              <ImageIconButton src={item.icon} size={68} />
              <Typography variant="body2" mt={1} color="secondary">
                {item.label}
              </Typography>
            </Paper>
          </Link>
        ))}
      </Box>
    </Box>
  );
};

export default HomeMenu;
